/** AI が使いがちな別名 → 実体（icons/manifest.json の aliases） */
export const iconAliases: Record<string, string> = {
  "expand_more": "keyboard_arrow_down",
  "expand_less": "keyboard_arrow_up",
  "done": "check",
  "file_download": "download",
  "file_upload": "upload",
  "insert_drive_file": "draft",
  "launch": "open_in_new",
  "place": "location_on",
  "phone": "call",
  "local_offer": "sell",
  "push_pin": "keep",
  "business": "domain",
  "laptop": "computer",
  "insights": "query_stats",
  "new_releases": "release_alert",
  "tips_and_updates": "lightbulb",
  "smartphone": "devices",
  "settings_suggest": "settings"
};

export const icons: Record<string, IconDef> = {
  ...defs,
  ...Object.fromEntries(Object.entries(iconAliases).map(([alias, target]) => [alias, defs[target]])),
};

/** 実体の名前（別名を含まない） */
export const iconNames = Object.keys(defs);
